//! Pinned native mutable Gantt public integration. Canonical reachable graphs
//! compare own descriptors, undefined, Maps/Sets, task and Date alias identity.
use pele::compat::{
    diagrams::gantt::{Gantt, GanttModel},
    public::{
        Atom, InvocationOutcome, JavaScriptErrorKind, JsString, MethodCall, ModelGraph,
        ModelSchema, Node, Property, PrototypeId, PublicDiagramModule, PublicDocument,
        PublicEngine, PublicError,
    },
    text::MetricsResources,
    *,
};
use serde_json::Value as Json;
use serde_json::{json, Value as J};
use sha2::{Digest, Sha256};
use std::{
    collections::HashMap,
    sync::{
        atomic::{AtomicUsize, Ordering},
        Arc,
    },
};
const NOW: f64 = 1704067200000.;
const SOURCE: &str = "gantt\ndateFormat YYYY-MM-DD\nsection S\nA:a,2024-01-01,1d\nB:b,after a,2d";
struct Host;
impl RenderResources for Host {
    fn now_millis(&mut self) -> Result<f64, PeleError> {
        Ok(NOW)
    }
    fn text_width(&mut self, r: TextRequest<'_>) -> Result<f64, PeleError> {
        MetricsResources.text_width(r)
    }
    fn parse_date(&mut self, s: &str) -> Result<Option<f64>, PeleError> {
        MetricsResources.parse_date(s)
    }
}
fn reference(value: &Atom) -> u32 {
    if let Atom::Ref(id) = value {
        *id
    } else {
        panic!("object reference expected")
    }
}

#[test]
fn gantt_construction_preserves_complete_native_arena_representation() {
    // Pin even unreachable nodes, intern order and bit patterns. The historical
    // Pele corpus below separately checks observable methods and rendering.
    let fixture: Json = serde_json::from_str(include_str!(
        "../../../fixtures/pele/gantt-construction.json"
    ))
    .unwrap();
    let engine = PublicEngine::with_builtins();
    for case in fixture["cases"].as_array().unwrap() {
        let options: RenderOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let document = engine
            .parse(case["source"].as_str().unwrap(), &options.parse)
            .unwrap();
        let graph = document.snapshot().unwrap();
        let binary = pele::compat::public::encode_binary_exchange(
            0,
            &graph,
            b"",
            pele::compat::public::DEFAULT_BINARY_BUDGET,
        )
        .unwrap();
        assert_eq!(graph.nodes.len(), case["nodes"].as_u64().unwrap() as usize);
        assert_eq!(
            graph.strings.len(),
            case["strings"].as_u64().unwrap() as usize
        );
        assert_eq!(binary.len(), case["binaryBytes"].as_u64().unwrap() as usize);
        assert_eq!(
            format!("{:x}", Sha256::digest(&binary)),
            case["graphSHA256"].as_str().unwrap(),
            "complete arena differs for {}",
            case["id"]
        );
    }
}
fn string(g: &mut ModelGraph, text: &str) -> Atom {
    let id = g.strings.len() as u32;
    g.strings.push(JsString::from(text));
    Atom::String(id)
}
fn property(g: &mut ModelGraph, id: u32, key: &str, value: Atom) {
    let existing = g.nodes[id as usize]
        .properties()
        .iter()
        .position(|p| g.strings[p.key as usize].is(key));
    if let Some(at) = existing {
        properties_mut(&mut g.nodes[id as usize])[at].value = value;
    } else {
        let key_id = g.strings.len() as u32;
        g.strings.push(JsString::from(key));
        properties_mut(&mut g.nodes[id as usize]).push(Property {
            key: key_id,
            value,
            flags: 7,
        });
    }
}
fn properties_mut(node: &mut Node) -> &mut Vec<Property> {
    match node {
        Node::Object { properties }
        | Node::Instance { properties, .. }
        | Node::Array { properties, .. }
        | Node::Map { properties, .. }
        | Node::Set { properties, .. }
        | Node::Date { properties, .. }
        | Node::Error { properties, .. } => properties,
    }
}
fn field<'a>(g: &'a ModelGraph, id: u32, key: &str) -> &'a Atom {
    &g.nodes[id as usize]
        .properties()
        .iter()
        .find(|p| g.strings[p.key as usize].is(key))
        .unwrap()
        .value
}
fn root(g: &ModelGraph) -> u32 {
    reference(&g.root)
}
fn array(g: &ModelGraph, id: u32) -> Vec<Atom> {
    let Node::Array { length, properties } = &g.nodes[id as usize] else {
        panic!()
    };
    let mut out = vec![Atom::Undefined; *length as usize];
    for p in properties {
        if let Some(index) = g.strings[p.key as usize]
            .well_formed()
            .and_then(|s| s.parse::<usize>().ok())
        {
            if index < out.len() && g.strings[p.key as usize].is(&index.to_string()) {
                out[index] = p.value.clone()
            }
        }
    }
    out
}
fn push_object(g: &mut ModelGraph, fields: Vec<(&str, Atom)>) -> u32 {
    let id = g.nodes.len() as u32;
    g.nodes.push(Node::Object { properties: vec![] });
    for (k, v) in fields {
        property(g, id, k, v)
    }
    id
}
fn push_array(g: &mut ModelGraph, values: Vec<Atom>) -> u32 {
    let id = g.nodes.len() as u32;
    let length = values.len() as u32;
    g.nodes.push(Node::Array {
        length,
        properties: vec![],
    });
    for (i, v) in values.into_iter().enumerate() {
        property(g, id, &i.to_string(), v)
    }
    id
}
struct Counted(Arc<AtomicUsize>);
impl DiagramModule for Counted {
    type Model = GanttModel;
    fn descriptor(&self) -> ModuleDescriptor {
        Gantt.descriptor()
    }
    fn parse(&self, c: ParseContext<'_>) -> Result<Self::Model, PeleError> {
        self.0.fetch_add(1, Ordering::SeqCst);
        Gantt.parse(c)
    }
    fn render(
        &self,
        m: &Self::Model,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        Gantt.render(m, c, o, h)
    }
}
impl PublicDiagramModule for Counted {
    type PublicState = <Gantt as PublicDiagramModule>::PublicState;
    fn model_schema(&self) -> &'static ModelSchema {
        Gantt.model_schema()
    }
    fn invoke_public(
        &self,
        s: &mut Self::PublicState,
        call: MethodCall,
        c: &Object,
        h: &mut dyn RenderResources,
    ) -> Result<Atom, PublicError> {
        Gantt.invoke_public(s, call, c, h)
    }
    fn create_public(&self, m: &GanttModel) -> Result<Self::PublicState, PeleError> {
        Gantt.create_public(m)
    }
    fn export_public(&self, s: &Self::PublicState) -> Result<ModelGraph, PeleError> {
        Gantt.export_public(s)
    }
    fn apply_public(&self, s: &mut Self::PublicState, g: ModelGraph) -> Result<(), PeleError> {
        Gantt.apply_public(s, g)
    }
    fn render_public_operation(
        &self,
        s: &mut Self::PublicState,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PublicError> {
        Gantt.render_public_operation(s, c, o, h)
    }
    fn render_public(
        &self,
        s: &mut Self::PublicState,
        c: &Object,
        o: &RenderSettings,
        h: &mut dyn RenderResources,
    ) -> Result<Rendered, PeleError> {
        Gantt.render_public(s, c, o, h)
    }
}
fn parsed(source: &str) -> PublicDocument {
    let mut e = PublicEngine::empty();
    e.register(Gantt);
    e.parse(source, &Default::default()).unwrap()
}
fn mapped(g: &ModelGraph, map: u32, name: &str) -> Atom {
    let Node::Map { entries, .. } = &g.nodes[map as usize] else {
        panic!()
    };
    entries
        .iter()
        .find(|(k, _)| matches!(k,Atom::String(id) if g.strings[*id as usize].is(name)))
        .unwrap()
        .1
        .clone()
}
fn keys(g: &ModelGraph, id: u32) -> Vec<String> {
    g.nodes[id as usize]
        .properties()
        .iter()
        .map(|p| g.strings[p.key as usize].well_formed().unwrap())
        .collect()
}
fn texts_of(g: &ModelGraph, id: u32) -> Vec<String> {
    array(g, id)
        .iter()
        .map(|a| g.text(a).unwrap().well_formed().unwrap())
        .collect()
}
fn method(doc: &mut PublicDocument, name: &str, args: Vec<Atom>) -> InvocationOutcome {
    let method = doc
        .model_schema()
        .methods
        .iter()
        .find(|m| m.name == name)
        .unwrap()
        .id;
    let receiver = doc.snapshot().unwrap().root;
    doc.invoke(
        doc.revision(),
        MethodCall {
            method,
            receiver,
            arguments: args,
        },
        &mut Host,
    )
    .unwrap()
}
fn apply_args(
    doc: &mut PublicDocument,
    make: impl FnOnce(&mut ModelGraph) -> Vec<Atom>,
) -> Vec<Atom> {
    let mut g = doc.snapshot().unwrap();
    let args = make(&mut g);
    doc.apply(doc.revision(), g).unwrap();
    args
}
fn invoke(
    doc: &mut PublicDocument,
    name: &str,
    make: impl FnOnce(&mut ModelGraph) -> Vec<Atom>,
) -> InvocationOutcome {
    let args = apply_args(doc, make);
    method(doc, name, args)
}
fn svg(doc: &mut PublicDocument) -> Rendered {
    doc.render(&Default::default(), &mut Host).unwrap().rendered
}
fn same_source(doc: &mut PublicDocument, source: &str) {
    assert_eq!(
        svg(doc),
        Engine::with_builtins()
            .render_source(source, &Default::default(), &mut Host)
            .unwrap()
            .rendered
    )
}
fn is_type_error(out: &InvocationOutcome, text: &str) {
    match &out.result {
        Err(PublicError::JavaScript {
            name: JavaScriptErrorKind::TypeError,
            message,
        }) => assert_eq!(message.well_formed().as_deref(), Some(text)),
        other => panic!("expected TypeError: {other:?}"),
    }
}
fn delete(g: &mut ModelGraph, id: u32, key: &str) {
    let position = g.nodes[id as usize]
        .properties()
        .iter()
        .position(|p| g.strings[p.key as usize].is(key));
    if let Some(n) = position {
        g.nodes[id as usize].properties_mut().remove(n);
    }
}
